INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l25','at last','',NULL,'/ət læst/','I arrived in London at last.','我终于到了伦敦。','At last, the bus came.','公交车终于来了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l25','not only ... but also','',NULL,'/nɑːt ˈoʊnli bʌt ˈɔːlsoʊ/','not only carefully but clearly as well','不但仔细而且清楚','She is not only smart but also kind.','她不但聪明而且善良。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l25','neither ... nor','',NULL,'/ˈniːðər nɔːr/','He spoke neither slowly nor clearly.','他说得既不慢也不清楚。','I like neither tea nor coffee.','茶和咖啡我都不喜欢。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l25','look at','',NULL,'/lʊk æt/','We looked at each other.','我们互相看着对方。','Look at the picture.','看这张图片。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp1','choice','{"stem":"把两个简单句连成并列句,常用哪些连词?","options":["the / a / an","very / too / quite","in / on / at","and / but / so / or 等"],"answer_index":3,"explanation_cn":"把两个简单句连起来常用并列连词:and(和)、but(但)、so(所以)、or(或)等。✓ He finished lunch and went out."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp1','choice','{"stem":"\"He finished lunch ___ went into the garden.\"(顺接:然后)","options":["but","nor","and","or"],"answer_index":2,"stem_cn":"他吃完午饭,然后走进了花园。","explanation_cn":"\"吃完午饭\"和\"走进花园\"顺着说,用 and 连接。✓ He finished lunch and went into the garden."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp1','choice','{"stem":"\"I ran to the station ___ missed the train.\"(转折:但是)","options":["so","but","or","and"],"answer_index":1,"stem_cn":"我跑到车站,但还是误了火车。","explanation_cn":"\"跑到车站\"却\"误了火车\",是转折,用 but。✓ I ran to the station but missed the train."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp2','choice','{"stem":"both A and B 的意思是:","options":["不但 A 而且 B","既不 A 也不 B","A 和 B 两者都","要么 A 要么 B"],"answer_index":2,"explanation_cn":"both A and B = A 和 B 两者都。✓ both tall and strong 又高又壮。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp2','choice','{"stem":"\"He is ___ tall and strong.\"(两者都:又高又壮)","options":["neither","either","not","both"],"answer_index":3,"stem_cn":"他又高又壮。","explanation_cn":"\"又高又壮\"是两者都,用 both … and。✓ He is both tall and strong."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp3','choice','{"stem":"either A or B 的意思是:","options":["不但 A 而且 B","要么 A 要么 B(二者选一)","既不 A 也不 B","A 和 B 都"],"answer_index":1,"explanation_cn":"either A or B = 要么 A 要么 B,二者选一。✓ either you or I。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp3','choice','{"stem":"\"Either you go ___ I go.\"(要么…要么)","options":["nor","but","and","or"],"answer_index":3,"stem_cn":"要么你去,要么我去。","explanation_cn":"either … or 成对使用,\"要么你去要么我去\"。✓ Either you go or I go."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp4','choice','{"stem":"neither A nor B 的意思是:","options":["要么 A 要么 B","既不 A 也不 B(两者都不)","不但 A 而且 B","A 和 B 都"],"answer_index":1,"explanation_cn":"neither A nor B = 既不 A 也不 B,两者都否定。✓ neither slowly nor clearly。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp4','choice','{"stem":"\"He spoke ___ slowly nor clearly.\"(既不…也不)","options":["not","both","either","neither"],"answer_index":3,"stem_cn":"他说得既不慢也不清楚。","explanation_cn":"\"既不慢也不清楚\"用 neither … nor。✓ He spoke neither slowly nor clearly."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp4','choice','{"stem":"\"I like neither tea ___ coffee.\"(既不…也不)","options":["and","or","nor","but"],"answer_index":2,"stem_cn":"茶和咖啡我都不喜欢。","explanation_cn":"neither 后面配 nor,\"茶和咖啡都不喜欢\"= neither tea nor coffee。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp5','choice','{"stem":"not only A but also B 的意思是:","options":["不但 A 而且 B","要么 A 要么 B","A 但不 B","既不 A 也不 B"],"answer_index":0,"explanation_cn":"not only A but also B = 不但 A 而且 B,两个都成立。✓ not only clever but also kind。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp5','choice','{"stem":"\"He is not only clever ___ also kind.\"(不但…而且)","options":["or","but","and","nor"],"answer_index":1,"stem_cn":"他不但聪明而且善良。","explanation_cn":"not only … but also 成对,\"不但聪明而且善良\"。✓ not only clever but also kind."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp5','choice','{"stem":"\"I spoke not only carefully but clearly ___.\"(不但…而且…:句尾用''也'')","options":["too much","also as","as","as well"],"answer_index":3,"stem_cn":"我说得不但仔细而且清楚。","explanation_cn":"not only … but … as well 也表示\"不但…而且\",as well 放句尾。✓ not only carefully but clearly as well."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp6','choice','{"stem":"\"I saw him yesterday ___ he did not greet me.\"(转折:但)","options":["or","and","but","so"],"answer_index":2,"stem_cn":"我昨天见到他,但他没理我。","explanation_cn":"\"见到他\"却\"没理我\",是转折,用 but。✓ I saw him yesterday but he did not greet me."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp6','choice','{"stem":"\"It was late, ___ we went home.\"(因此)","options":["so","but","or","nor"],"answer_index":0,"stem_cn":"天晚了,所以我们回家了。","explanation_cn":"\"天晚了\"因此\"回家\",是因果,用 so。✓ It was late, so we went home."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp7','choice','{"stem":"\"British people ___ tea very much.\"(people 作主语,用复数动词)","options":["likes","is","was","like"],"answer_index":3,"stem_cn":"英国人非常喜欢喝茶。","explanation_cn":"British people 是复数主语,动词用复数 like。✓ British people like tea. 顺带记:people 作主语永远配复数,可套 Chinese/American people like…。📌 the English = English people 是书面/正式说法,口语常说 British people。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp7','choice','{"stem":"\"Many people ___ coffee in the morning.\"(people 作主语,用复数动词)","options":["is","drink","drinks","was"],"answer_index":1,"stem_cn":"许多人早上喝咖啡。","explanation_cn":"people 是复数主语,动词用复数 drink。✓ Many people drink coffee in the morning. 顺带记:people 永远当复数,不说 drinks。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',5,'am2_l25_gp8','choice','{"stem":"at last 的意思是:","options":["偶尔","从不","立刻","终于,最后"],"answer_index":3,"explanation_cn":"at last = 终于、最后。✓ I arrived in London at last 我终于到了伦敦。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"美语\"火车站\"常说:","options":["car station","rail house","train station","railway station"],"answer_index":2,"explanation_cn":"美语\"火车站\"常说 train station;英式说 railway station。✓ at the train station 在火车站。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"美语\"铁路\"常说:","options":["trainway","railway","ironroad","railroad"],"answer_index":3,"explanation_cn":"美语\"铁路\"常说 railroad;英式说 railway。✓ a railroad line 一条铁路。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"at last 的意思是:","options":["偶尔","立刻","终于,最后","从不"],"answer_index":2,"explanation_cn":"at last = 终于、最后。✓ At last he understood 他终于听懂了。\n顺带记:立刻 = at once;从不 = never;偶尔 = sometimes."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"not only ... but also 的意思是:","options":["虽然…但是…","不但…而且…","既不…也不…","要么…要么…"],"answer_index":1,"explanation_cn":"not only … but also = 不但…而且…,两个都成立。✓ not only careful but also clear。\n顺带记:既不…也不 = neither … nor;要么…要么 = either … or;虽然…但是 = although … (yet)."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"neither ... nor 的意思是:","options":["又…又…","要么…要么…","不但…而且…","既不…也不…"],"answer_index":3,"explanation_cn":"neither … nor = 既不…也不…,两个都否定。✓ neither slowly nor clearly。\n顺带记:不但…而且 = not only … but also;要么…要么 = either … or;又…又 = both … and."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',6,NULL,'choice','{"stem":"look at each other 的意思是:","options":["看向别处","互相看着对方","互相帮助","彼此争吵"],"answer_index":1,"explanation_cn":"look at each other = 互相看着对方。✓ We looked at each other and smiled 我们相视一笑。\n顺带记:看向别处 = look away;互相帮助 = help each other;彼此争吵 = argue with each other."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',7,NULL,'cloze','{"stem":"第 1 空","context":"I spoke not only carefully ___1___ clearly. The porter could not understand me, ___2___ I repeated my question. He spoke ___3___ slowly nor clearly. Either he was confused, ___4___ my English was strange!","blank_no":1,"options":["but","and","nor","so"],"answer_index":0,"explanation_cn":"not only 后面配 but,\"不但仔细而且清楚\"= not only carefully but clearly。✓\n✗ and:not only 要配 but,不配 and;✗ nor:nor 是配 neither 的;✗ so:so 表因果,这里不对."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',7,NULL,'cloze','{"stem":"第 2 空","context":"I spoke not only carefully ___1___ clearly. The porter could not understand me, ___2___ I repeated my question. He spoke ___3___ slowly nor clearly. Either he was confused, ___4___ my English was strange!","blank_no":2,"options":["so","but","or","nor"],"answer_index":0,"explanation_cn":"\"听不懂\"所以\"重复问话\",是因果,用 so。✓ He could not understand me, so I repeated it.\n✗ but:这里是因果不是转折;✗ or:or 表选择,不对;✗ nor:nor 表\"也不\",不对."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',7,NULL,'cloze','{"stem":"第 3 空","context":"I spoke not only carefully ___1___ clearly. The porter could not understand me, ___2___ I repeated my question. He spoke ___3___ slowly nor clearly. Either he was confused, ___4___ my English was strange!","blank_no":3,"options":["neither","either","both","not"],"answer_index":0,"explanation_cn":"后面有 nor,前面配 neither,\"既不慢也不清楚\"。✓ neither slowly nor clearly.\n✗ either:either 配 or,不配 nor;✗ both:both 配 and;✗ not:not 不和 nor 成对."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',7,NULL,'cloze','{"stem":"第 4 空","context":"I spoke not only carefully ___1___ clearly. The porter could not understand me, ___2___ I repeated my question. He spoke ___3___ slowly nor clearly. Either he was confused, ___4___ my English was strange!","blank_no":4,"options":["or","nor","and","but"],"answer_index":0,"explanation_cn":"前面有 Either,后面配 or,\"要么…要么…\"。✓ Either he was confused, or my English was strange.\n✗ nor:nor 配 neither,不配 either;✗ and:either 不配 and;✗ but:either 不配 but."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',8,NULL,'choice','{"stem":"Where did the writer arrive?","options":["At a hotel in New York","In Paris","At an airport","In London, at the train station"],"answer_index":3,"explanation_cn":"课文说 I arrived in London… The train station was big,作者到了伦敦的火车站。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',8,NULL,'choice','{"stem":"Who did the writer ask for directions?","options":["A taxi driver","A police officer","A porter","A teacher"],"answer_index":2,"explanation_cn":"课文说 I asked a porter,作者向一个搬运工问路。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',8,NULL,'choice','{"stem":"Could the writer understand the porter at first?","options":["No, the porter spoke neither slowly nor clearly","Yes, very easily","Yes, the porter spoke Chinese","No, the porter said nothing"],"answer_index":0,"explanation_cn":"课文说 he spoke neither slowly nor clearly,搬运工说得又快又含糊,所以听不懂。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',9,NULL,'choice','{"stem":"你想说\"他不但会唱歌而且会跳舞\"(not only ... but also):","options":["He not only can sing but dance also.","He can not only sing but also dances.","He can sing not only but also dance.","He can not only sing but also dance."],"answer_index":3,"explanation_cn":"\"不但…而且…\"用 not only … but also,后面都接动词原形。✓ He can not only sing but also dance. 场合:夸某人多才多艺。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',9,NULL,'choice','{"stem":"你想说\"我既不喜欢茶也不喜欢咖啡\"(neither ... nor):","options":["I like neither tea and coffee.","I like neither tea nor coffee.","I like neither tea or coffee.","I like either tea nor coffee."],"answer_index":1,"explanation_cn":"\"既不…也不…\"用 neither … nor。✓ I like neither tea nor coffee. 场合:两样都不喜欢时说。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',9,NULL,'choice','{"stem":"你想说\"要么你去要么我去\"(either ... or):","options":["Both you go or I go.","Either you go nor I go.","Either you go or I go.","Neither you go or I go."],"answer_index":2,"explanation_cn":"\"要么…要么…\"用 either … or。✓ Either you go or I go. 场合:二选一时说。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"foreigner 的意思是:","options":["外国人","陌生人","外交官","游客"],"answer_index":0,"explanation_cn":"foreigner = 外国人。✓ I am a foreigner 我是个外国人。\n顺带记:陌生人 = stranger;外交官 = diplomat;游客 = tourist."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"wonder 的意思是:","options":["抱怨","确信","回答","感到奇怪,想知道"],"answer_index":3,"explanation_cn":"wonder = 感到奇怪、想知道。✓ I wonder 我感到奇怪。\n顺带记:确信 = be sure;抱怨 = complain;回答 = answer."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"\"He is not only clever ___ also kind.\"(不但…而且)","options":["and","but","nor","or"],"answer_index":1,"stem_cn":"他不但聪明而且善良。","explanation_cn":"not only … but also 成对,\"不但聪明而且善良\"。✓ not only clever but also kind."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"\"___ you nor I can do it.\"(…都不能)","options":["Either","Both","Neither","Not"],"answer_index":2,"stem_cn":"你和我都做不了这件事。","explanation_cn":"后面有 nor,前面用 Neither,\"你和我都不能\"。✓ Neither you nor I can do it."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"\"Do they speak English?\" 这句话的意思是:","options":["他们说的是英语吗?","请说英语。","他们会说英语。","他们不说英语。"],"answer_index":0,"explanation_cn":"Do they speak English? 是疑问句,意思是\"他们说的是英语吗?\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"\"You''ll soon learn English.\" 这句话的意思是:","options":["你已经学会英语了。","你必须学英语。","你很快就会学会英语。","你学不会英语。"],"answer_index":2,"explanation_cn":"You''ll soon learn English. 意思是\"你很快就会学会英语\"。You''ll = You will。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"Why couldn''t the writer understand the porter?","options":["The porter spoke neither slowly nor clearly","The writer was deaf","The porter whispered","The porter spoke Chinese"],"answer_index":0,"passage":"I arrived in London at last. The train station was big, black, and dark. I did not know the way to my hotel, so I asked a porter. I not only spoke English very carefully, but very clearly as well. The porter, however, could not understand me. I repeated my question several times, and at last he understood. He answered me, but he spoke neither slowly nor clearly. ''I am a foreigner,'' I said. Then he spoke slowly, but I could not understand him. My teacher never spoke English like that! The porter and I looked at each other and smiled. Then he said something and I understood it. ''You''ll soon learn English!'' he said. I wonder. In England, each person seems to speak a different language. The English understand each other, but I don''t understand them! Do they speak English?","explanation_cn":"课文说搬运工 spoke neither slowly nor clearly,又快又含糊,所以听不懂。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"What did the porter say at the end?","options":["''Go away!''","''I don''t know.''","''You''ll soon learn English!''","''Speak louder!''"],"answer_index":2,"passage":"I arrived in London at last. The train station was big, black, and dark. I did not know the way to my hotel, so I asked a porter. I not only spoke English very carefully, but very clearly as well. The porter, however, could not understand me. I repeated my question several times, and at last he understood. He answered me, but he spoke neither slowly nor clearly. ''I am a foreigner,'' I said. Then he spoke slowly, but I could not understand him. My teacher never spoke English like that! The porter and I looked at each other and smiled. Then he said something and I understood it. ''You''ll soon learn English!'' he said. I wonder. In England, each person seems to speak a different language. The English understand each other, but I don''t understand them! Do they speak English?","explanation_cn":"课文结尾搬运工说 ''You''ll soon learn English!''(您很快会学会英语的!)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"Why does the writer joke that he can''t understand the English?","options":["Their spoken English sounds different from his teacher''s","They only speak French","They speak too quietly","They never talk to him"],"answer_index":0,"audio":"I arrived in London at last. The train station was big, black, and dark. I did not know the way to my hotel, so I asked a porter. I not only spoke English very carefully, but very clearly as well. The porter, however, could not understand me. I repeated my question several times, and at last he understood. He answered me, but he spoke neither slowly nor clearly. ''I am a foreigner,'' I said. Then he spoke slowly, but I could not understand him. My teacher never spoke English like that! The porter and I looked at each other and smiled. Then he said something and I understood it. ''You''ll soon learn English!'' he said. I wonder. In England, each person seems to speak a different language. The English understand each other, but I don''t understand them! Do they speak English?","explanation_cn":"作者说 My teacher never spoke English like that,街上的英语和老师教的不一样,所以听不懂。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l25',10,NULL,'choice','{"stem":"How did the writer and the porter feel toward the end?","options":["They got angry","They started shouting","They looked at each other and smiled","They walked away"],"answer_index":2,"audio":"I arrived in London at last. The train station was big, black, and dark. I did not know the way to my hotel, so I asked a porter. I not only spoke English very carefully, but very clearly as well. The porter, however, could not understand me. I repeated my question several times, and at last he understood. He answered me, but he spoke neither slowly nor clearly. ''I am a foreigner,'' I said. Then he spoke slowly, but I could not understand him. My teacher never spoke English like that! The porter and I looked at each other and smiled. Then he said something and I understood it. ''You''ll soon learn English!'' he said. I wonder. In England, each person seems to speak a different language. The English understand each other, but I don''t understand them! Do they speak English?","explanation_cn":"课文说 The porter and I looked at each other and smiled,两人相视一笑。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l26',2,4,26,'The best art critics','最佳艺术评论家','一般现在时(主考:表经常/习惯性动作 · 表客观真理 The earth goes round the sun · 第三人称单数动词 +s/es · 状态动词 like/know/understand 不用进行时 · 对比现在进行时''此刻正在'')+ whether 引导宾语从句 / one 代替名词(辅考)','学美术的''我''画了很多画;大人爱假装懂现代艺术,其实小孩子才最会欣赏——七岁的妹妹一眼看出我新挂的画''是不是挂倒了'',一看,果然倒了!','{"q":"Listen and answer — Who is the student''s best critic?","options":["His seven-year-old sister","His art teacher","A famous painter","His mother"],"answer_index":0}'::jsonb,'{"title":"说''经常发生的事''(一般现在时)","intro":"本课讲一般现在时——表示经常/习惯做的事、客观真理。注意:主语是第三人称单数时动词加 -s/es;like/know/understand 这类表状态的词不用进行时。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["表经常/习惯:一般现在时","I paint a lot of pictures."],["表客观真理:一般现在时","The earth goes round the sun."],["第三人称单数:动词 +s/es","My sister appreciates modern art."],["like/know/understand 等状态词不用进行时","I understand what you mean.(不说 am understanding)"]]},"specialRules":[{"rule":"对比:I am having breakfast(此刻正在)↔ I always get up late(经常)","mark":"现在进行 vs 一般现在"},{"rule":"whether = 是否,引导宾语从句:She tells me whether it is good.","mark":"whether 是否"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',1,NULL,'I am an art student, and I paint a lot of pictures.','我是个学艺术的学生,画了很多画。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',2,NULL,'Many people pretend that they understand modern art.','有很多人装成很懂现代艺术的样子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',3,NULL,'They always tell you what a picture is ''about''. Of course, many pictures are not ''about'' anything.','他们总是告诉你一幅画的''意思''是什么。当然,有很多画根本没什么''意思''。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',4,NULL,'They are just pretty patterns. We like them in the same way that we like pretty curtain material.','它们只是些好看的图案。我们喜欢它们,就像我们喜欢漂亮的窗帘布一样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',5,NULL,'I think that young children often appreciate modern pictures better than anyone else. They notice more.','我觉得小孩子往往比任何人都更能欣赏现代绘画,他们观察到的东西更多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',6,NULL,'My sister is only seven, but she always tells me whether my pictures are good or not.','我妹妹只有七岁,但她总能说出我的画是好还是坏。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',7,NULL,'She came into my room yesterday. ''What are you doing?'' she asked.','昨天她到我房里来了。"你在干什么呢?"她问。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',8,NULL,'''I''m hanging this picture on the wall,'' I answered. ''It''s a new one. Do you like it?''','"我正把这幅画挂到墙上去,"我回答说,"这是幅新画,你喜欢吗?"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',9,NULL,'She looked at it critically for a moment. ''It''s all right,'' she said, ''but isn''t it upside down?''','她用挑剔的目光看了一会儿。"还可以吧,"她说,"不过,是不是挂倒了?"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l26',10,NULL,'I looked at it again. She was right! It was!','我再次看了看画。她说对了!是挂倒了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
