INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l27','put up','',NULL,'/pʊt ʌp/','They put up their tent.','他们搭起帐篷。','Let''s put up the tent here.','咱们把帐篷搭在这儿吧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l27','put out','',NULL,'/pʊt aʊt/','They put out the fire.','他们熄灭了火。','Please put out the campfire.','请把篝火熄灭。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l27','as soon as','',NULL,'/əz suːn əz/','As soon as this was done, they cooked a meal.','这一做完,他们就做起饭来。','Call me as soon as you arrive.','你一到就给我打电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l27','in the middle of','',NULL,'/ɪn ðə ˈmɪdl əv/','In the middle of the night, two boys woke up.','半夜里,两个男孩醒了。','The tent was in the middle of a field.','帐篷在田野中央。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp1','choice','{"stem":"\"We ___ a movie yesterday evening.\"(过去发生:watch)","options":["are watching","watched","watch","will watch"],"answer_index":1,"stem_cn":"昨晚我们看了场电影。","explanation_cn":"过去发生并已结束的动作,用一般过去时 watched。✓ We watched a movie yesterday evening."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp1','choice','{"stem":"\"They ___ a meal over an open fire.\"(过去发生:一般过去时)","options":["will cook","are cooking","cook","cooked"],"answer_index":3,"stem_cn":"他们在篝火上做了一顿饭。","explanation_cn":"\"在火上做了饭\"是过去发生的事,用一般过去时 cooked。✓ They cooked a meal over an open fire."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp2','choice','{"stem":"\"She ___ the door and went out.\"(open 的过去式,规则加 -ed)","options":["opens","opened","is opening","open"],"answer_index":1,"stem_cn":"她打开门走了出去。","explanation_cn":"规则动词过去式在词尾加 -ed:open → opened。✓ She opened the door and went out."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp2','choice','{"stem":"\"They ___ outside in the rain.\"(hurry 的过去式)","options":["will hurry","are hurrying","hurry","hurried"],"answer_index":3,"stem_cn":"他们匆忙跑到外面雨中。","explanation_cn":"\"匆忙跑到外面\"是过去发生;hurry 以辅音字母+y 结尾,变 y 为 i 再加 -ed → hurried。✓ They hurried outside."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp3','choice','{"stem":"\"They ___ stories and sang songs.\"(tell 的过去式)","options":["told","are telling","telled","tell"],"answer_index":0,"stem_cn":"他们讲故事、唱歌。","explanation_cn":"\"讲故事\"是过去发生;tell 是不规则动词,过去式是 told。✓ They told stories and sang songs."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp3','choice','{"stem":"\"Two boys ___ up in the night.\"(wake 的过去式)","options":["are waking","waked","wake","woke"],"answer_index":3,"stem_cn":"两个男孩夜里醒了。","explanation_cn":"\"夜里醒了\"是过去发生;wake 是不规则动词,过去式是 woke。✓ Two boys woke up in the night."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp3','choice','{"stem":"\"The boys ___ tired.\"(feel 的过去式)","options":["feel","feeled","felt","are feeling"],"answer_index":2,"stem_cn":"男孩们感到累了。","explanation_cn":"\"感到累了\"是过去发生;feel 是不规则动词,过去式是 felt。✓ The boys felt tired."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp3','choice','{"stem":"\"A stream ___ its way across the field.\"(wind 蜿蜒 的过去式)","options":["is winding","wound","wind","winded"],"answer_index":1,"stem_cn":"一条小溪蜿蜒流过田野。","explanation_cn":"\"小溪蜿蜒流过\"是过去发生;wind 是不规则动词,过去式是 wound(读 /waʊnd/)。✓ The stream wound its way across the field."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp4','choice','{"stem":"\"They ___ see the stream in the dark.\"(过去否定:没看见)","options":["did not","was not","were not","do not"],"answer_index":0,"stem_cn":"黑暗中他们没看见那条小溪。","explanation_cn":"一般过去时否定 = did not + 动词原形。✓ They did not see the stream in the dark."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp4','choice','{"stem":"\"They ___ hear the rain at first.\"(过去时否定)","options":["have not","do not","were not","did not"],"answer_index":3,"stem_cn":"他们起初没听见雨声。","explanation_cn":"\"起初没听见\"是过去时否定,用 did not + 动词原形 hear。✓ They did not hear the rain at first."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp5','choice','{"stem":"\"___ the boys hear the rain at first?\"(过去时一般疑问,用助动词提问)","options":["Do","Did","Was","Were"],"answer_index":1,"stem_cn":"男孩们一开始听见雨声了吗?","explanation_cn":"一般过去时的一般疑问句:Did + 主语 + 动词原形。✓ Did the boys hear the rain at first?"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp5','choice','{"stem":"\"___ they cook a meal over the fire?\"(过去时一般疑问)","options":["Do","Was","Did","Were"],"answer_index":2,"stem_cn":"他们在火上做饭了吗?","explanation_cn":"过去时一般疑问句用 Did 开头,后面动词用原形 cook。✓ Did they cook a meal over the fire?"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp6','choice','{"stem":"下面哪个词表示''过去''的时间,常配一般过去时?","options":["last night","now","every day","tomorrow"],"answer_index":0,"explanation_cn":"last night(昨晚)表示过去的时间,常配一般过去时。✓ They arrived last night. now/every day/tomorrow 都不是过去。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp6','choice','{"stem":"\"It ___ to rain some time later.\"(begin 的过去式)","options":["begins","begun","began","is beginning"],"answer_index":2,"stem_cn":"过了一会儿开始下雨了。","explanation_cn":"\"开始下雨\"是过去发生;begin 是不规则动词,过去式是 began。✓ It began to rain some time later."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp6','choice','{"stem":"\"They ___ soundly in their sleeping bags.\"(sleep 的过去式)","options":["sleep","are sleeping","sleeped","slept"],"answer_index":3,"stem_cn":"他们在睡袋里睡得很香。","explanation_cn":"\"睡得很香\"是过去发生;sleep 是不规则动词,过去式是 slept。✓ They slept soundly."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp6','choice','{"stem":"\"They ___ that a stream had formed.\"(find 的过去式)","options":["found","find","are finding","finded"],"answer_index":0,"stem_cn":"他们发现形成了一条小溪。","explanation_cn":"\"发现小溪\"是过去发生;find 是不规则动词,过去式是 found。✓ They found that a stream had formed."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp7','choice','{"stem":"\"___ this was done, they cooked a meal.\"(一……就……)","options":["In case","Unless","As soon as","Although"],"answer_index":2,"stem_cn":"这一做完,他们就做饭。","explanation_cn":"as soon as = \"一……就……\",引导时间从句。✓ As soon as this was done, they cooked a meal 这一做完,他们就做饭。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',5,'am2_l27_gp8','choice','{"stem":"\"The boys felt tired ___ they put out the fire.\"(所以/因此)","options":["so","nor","but","or"],"answer_index":0,"stem_cn":"男孩们累了,所以熄了火。","explanation_cn":"\"累了\"和\"熄了火\"是因果关系,用 so(所以/因此)连接。✓ The boys felt tired so they put out the fire."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"美语里\"手电筒\"常说:","options":["hand light","flashlight","torch","night lamp"],"answer_index":1,"explanation_cn":"美语\"手电筒\"说 flashlight;英式说 torch。✓ turn on the flashlight 打开手电筒。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"wonderful 的意思是:","options":["昂贵的","糟糕的","普通的","极好的"],"answer_index":3,"explanation_cn":"wonderful = 极好的、精彩的。✓ a wonderful meal 一顿美餐。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"creep 的意思是:","options":["飞行","奔跑","爬行,悄悄地行进","跳跃"],"answer_index":2,"explanation_cn":"creep = 爬行、悄悄地行进。✓ crept into their tent 悄悄钻进帐篷。\n顺带记:奔跑 = run;跳跃 = leap;飞行 = fly."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"soundly 的意思是(sleep soundly):","options":["焦虑地","短暂地","大声地","香甜地,酣畅地"],"answer_index":3,"explanation_cn":"soundly = (睡得)香甜、酣畅。✓ slept soundly 睡得很香。\n顺带记:大声地 = loudly;焦虑地 = anxiously;短暂地 = briefly."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"leap 的意思是:","options":["坐下","躺下","跳跃,跳起","转身"],"answer_index":2,"explanation_cn":"leap = 跳跃、跳起。✓ leapt out of the sleeping bags 从睡袋里跳出来。\n顺带记:坐下 = sit down;躺下 = lie down;转身 = turn round."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',6,NULL,'choice','{"stem":"form 的意思是(a stream formed):","options":["消失","形成","加热","移动"],"answer_index":1,"explanation_cn":"form = 形成、生成。✓ a stream formed in the field 田里形成了一条小溪。\n顺带记:消失 = disappear;加热 = heat;移动 = move."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',7,NULL,'cloze','{"stem":"第 1 空","context":"Late in the afternoon, the boys ___1___ up their tent. After a wonderful meal, they ___2___ stories by the fire. Some time later it began to rain, so they ___3___ into their tent. In the middle of the night, they ___4___ that a stream had formed in the field.","blank_no":1,"options":["put","putted","are putting","will put"],"answer_index":0,"explanation_cn":"过去发生用一般过去时;put 是不规则动词,过去式还是 put(不变)。✓ The boys put up their tent.\n✗ putted:put 过去式不加 -ted,仍是 put;✗ are putting:are putting 是此刻正在,不是过去;✗ will put:will put 是将来."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',7,NULL,'cloze','{"stem":"第 2 空","context":"Late in the afternoon, the boys ___1___ up their tent. After a wonderful meal, they ___2___ stories by the fire. Some time later it began to rain, so they ___3___ into their tent. In the middle of the night, they ___4___ that a stream had formed in the field.","blank_no":2,"options":["told","telled","tell","are telling"],"answer_index":0,"explanation_cn":"过去发生用一般过去时;tell 的过去式是 told。✓ They told stories by the fire.\n✗ telled:tell 是不规则动词,过去式是 told 不是 telled;✗ tell:tell 是原形,没体现过去;✗ are telling:are telling 是此刻正在,不是过去."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',7,NULL,'cloze','{"stem":"第 3 空","context":"Late in the afternoon, the boys ___1___ up their tent. After a wonderful meal, they ___2___ stories by the fire. Some time later it began to rain, so they ___3___ into their tent. In the middle of the night, they ___4___ that a stream had formed in the field.","blank_no":3,"options":["crept","creeped","creep","are creeping"],"answer_index":0,"explanation_cn":"过去发生用一般过去时;creep 的过去式是 crept。✓ They crept into their tent.\n✗ creeped:creep 是不规则动词,过去式是 crept 不是 creeped;✗ creep:creep 是原形;✗ are creeping:are creeping 是此刻正在,不是过去."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',7,NULL,'cloze','{"stem":"第 4 空","context":"Late in the afternoon, the boys ___1___ up their tent. After a wonderful meal, they ___2___ stories by the fire. Some time later it began to rain, so they ___3___ into their tent. In the middle of the night, they ___4___ that a stream had formed in the field.","blank_no":4,"options":["found","finded","find","are finding"],"answer_index":0,"explanation_cn":"过去发生用一般过去时;find 的过去式是 found。✓ They found that a stream had formed.\n✗ finded:find 是不规则动词,过去式是 found 不是 finded;✗ find:find 是原形;✗ are finding:are finding 是此刻正在,不是过去."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',8,NULL,'choice','{"stem":"Where did the boys put up their tent?","options":["In a forest","On a mountain top","In the middle of a field","By the sea"],"answer_index":2,"explanation_cn":"课文说 the boys put up their tent in the middle of a field,帐篷搭在田野中央。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',8,NULL,'choice','{"stem":"Why did two boys wake up in the night?","options":["Someone called them","It was too cold","They heard a wild animal","The tent was full of water"],"answer_index":3,"explanation_cn":"课文说 two boys woke up… The tent was full of water,他们醒来是因为帐篷里灌满了水。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',8,NULL,'choice','{"stem":"What had happened outside the tent?","options":["A stream had formed in the field","The fire had spread","Another tent had blown away","A tree had fallen down"],"answer_index":0,"explanation_cn":"课文说 they found that a stream had formed in the field,外面田里形成了一条小溪。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',9,NULL,'choice','{"stem":"你想说\"他们昨天搭起了帐篷\"(过去发生用一般过去时):","options":["They are putting up their tent yesterday.","They put up their tent tomorrow.","They put up their tent yesterday.","They will put up their tent yesterday."],"answer_index":2,"explanation_cn":"yesterday(昨天)是过去的时间,用一般过去时;put 的过去式还是 put。✓ They put up their tent yesterday. 场合:说昨天做过的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',9,NULL,'choice','{"stem":"你想说\"他们没有听见雨声\"(过去时否定):","options":["They will not hear the rain.","They are not hearing the rain.","They do not hear the rain.","They did not hear the rain."],"answer_index":3,"explanation_cn":"过去没做某事,用 did not + 动词原形 hear。✓ They did not hear the rain. 场合:说过去没听见、没做到某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',9,NULL,'choice','{"stem":"你想说\"你昨晚睡得好吗?\"(过去时疑问):","options":["Did you sleep well last night?","Are you sleeping well last night?","Do you sleep well last night?","Will you sleep well last night?"],"answer_index":0,"explanation_cn":"问过去的事,用 Did 开头,后面动词用原形 sleep。✓ Did you sleep well last night? 场合:问别人昨晚睡得好不好。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"stream 的意思是:","options":["沙漠","森林","小溪","山峰"],"answer_index":2,"explanation_cn":"stream = 小溪。✓ a stream had formed 形成了一条小溪。\n顺带记:森林 = forest;山峰 = peak;沙漠 = desert."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"comfortable 的意思是:","options":["潮湿的","狭窄的","破旧的","舒适的,安逸的"],"answer_index":3,"explanation_cn":"comfortable = 舒适的、安逸的。✓ warm and comfortable 又暖和又舒服。\n顺带记:破旧的 = shabby;潮湿的 = damp;狭窄的 = narrow."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"\"They ___ songs by the campfire.\"(sing 的过去式)","options":["sang","singed","are singing","sing"],"answer_index":0,"stem_cn":"他们在篝火旁唱歌。","explanation_cn":"\"唱歌\"是过去发生;sing 是不规则动词,过去式是 sang。✓ They sang songs by the campfire."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"\"They ___ out of their sleeping bags.\"(leap 的过去式)","options":["will leap","are leaping","leapt","leap"],"answer_index":2,"stem_cn":"他们从睡袋里跳出来。","explanation_cn":"\"跳出睡袋\"是过去发生;leap 的过去式是 leapt。✓ They leapt out of their sleeping bags."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"\"The tent was full of water!\" 这句话的意思是:","options":["帐篷里灌满了水!","帐篷被吹走了!","帐篷着火了!","帐篷很暖和!"],"answer_index":0,"explanation_cn":"The tent was full of water! 意思是\"帐篷里灌满了水!\"。full of = 装满了。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"\"A stream had formed in the field.\" 这句话的意思是:","options":["田野结了冰。","田野里形成了一条小溪。","田里长满了草。","田里起了大雾。"],"answer_index":1,"explanation_cn":"A stream had formed in the field. 意思是\"田野里(已经)形成了一条小溪\"。form = 形成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"Why did the boys hurry outside in the night?","options":["They wanted to see the stars","They were hungry again","Their tent was full of water","They heard a noise in the forest"],"answer_index":2,"passage":"Late in the afternoon, the boys put up their tent in the middle of a field. As soon as this was done, they cooked a meal over an open fire. They were all hungry and the food smelled good. After a wonderful meal, they told stories and sang songs by the campfire. But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent. Their sleeping bags were warm and comfortable, so they all slept soundly. In the middle of the night, two boys woke up and began shouting. The tent was full of water! They all leapt out of their sleeping bags and hurried outside. It was raining heavily and they found that a stream had formed in the field. The stream wound its way across the field and then flowed right under their tent!","explanation_cn":"课文说帐篷灌满了水,他们才 hurried outside,匆忙跑到外面。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"What did the boys find outside?","options":["A wild animal near the fire","A stream had formed and flowed under their tent","Their food was gone","Another group of campers"],"answer_index":1,"passage":"Late in the afternoon, the boys put up their tent in the middle of a field. As soon as this was done, they cooked a meal over an open fire. They were all hungry and the food smelled good. After a wonderful meal, they told stories and sang songs by the campfire. But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent. Their sleeping bags were warm and comfortable, so they all slept soundly. In the middle of the night, two boys woke up and began shouting. The tent was full of water! They all leapt out of their sleeping bags and hurried outside. It was raining heavily and they found that a stream had formed in the field. The stream wound its way across the field and then flowed right under their tent!","explanation_cn":"课文说外面 a stream had formed…and then flowed right under their tent,小溪正好从帐篷底下流过。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"What happened to the boys in the night?","options":["They got lost in the dark","Their fire went out of control","They ran out of food","Their tent was flooded by a stream"],"answer_index":3,"audio":"Late in the afternoon, the boys put up their tent in the middle of a field. As soon as this was done, they cooked a meal over an open fire. They were all hungry and the food smelled good. After a wonderful meal, they told stories and sang songs by the campfire. But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent. Their sleeping bags were warm and comfortable, so they all slept soundly. In the middle of the night, two boys woke up and began shouting. The tent was full of water! They all leapt out of their sleeping bags and hurried outside. It was raining heavily and they found that a stream had formed in the field. The stream wound its way across the field and then flowed right under their tent!","explanation_cn":"课文讲半夜一条小溪流到帐篷底下,把帐篷淹了,所以孩子们惊醒。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l27',10,NULL,'choice','{"stem":"How did the boys feel after the wonderful meal?","options":["Frightened","Bored","Tired","Angry"],"answer_index":2,"audio":"Late in the afternoon, the boys put up their tent in the middle of a field. As soon as this was done, they cooked a meal over an open fire. They were all hungry and the food smelled good. After a wonderful meal, they told stories and sang songs by the campfire. But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent. Their sleeping bags were warm and comfortable, so they all slept soundly. In the middle of the night, two boys woke up and began shouting. The tent was full of water! They all leapt out of their sleeping bags and hurried outside. It was raining heavily and they found that a stream had formed in the field. The stream wound its way across the field and then flowed right under their tent!","explanation_cn":"课文说 The boys felt tired so they put out the fire,吃完美餐后孩子们感到累了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l28',2,4,28,'No parking','禁止停车','现在完成时复习(主考:have/has + 过去分词 · since + 过去时间点/从句 · for + 一段时间 · up till now/so far 至今 · ever/just/already 位置 · have been to 去过 vs have gone to 去了没回)+ 定语从句 who/which/that/whose(辅考:指人/指物/所属,作主语不可省)','贾斯珀·怀特刚在城里买了新房,可自从搬进去,就老有人把车停在他家大门外,他自己的车一次都开不进车库;''禁止停车''的牌子毫无效果,于是他在门上装了一个丑陋的美杜莎石雕头像,盼着能把车和车主都变成石头——不过至今还没一个变成石头呢!','{"q":"Listen and answer — What is Jasper White''s problem?","options":["People keep parking cars outside his gate","He has lost his house key","His car has broken down","He can''t find a parking sign"],"answer_index":0}'::jsonb,'{"title":"说''到现在已经…''(现在完成时)","intro":"本课复习现在完成时——have/has + 过去分词,表示到现在为止已发生或完成的事。注意:since 接过去的时间点,for 接一段时间;up till now / so far 表''至今''。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["构成:have/has + 过去分词","He has just bought a new house."],["since + 过去时间点(自从)","I have not seen Tim since 1994."],["for + 一段时间(持续多久)","Tim has been abroad for three years."],["up till now / so far(至今为止)","Up till now he has won five prizes."]]},"specialRules":[{"rule":"been to = 去过(回来了);gone to = 去了(还没回):I have been to New York.","mark":"been to vs gone to"},{"rule":"定语从句:who/that 指人、which 指物、whose 表所属;作主语不能省:the people who believe…","mark":"who/which/that"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',1,NULL,'Jasper White is one of those rare people who believes in ancient myths.','贾斯珀·怀特是少有的相信古代神话的人之一。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',2,NULL,'He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners.','他刚在城里买下一所新房子,但自从搬进去后,就和汽车及车主们发生了摩擦。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',3,NULL,'When he returns home at night, he always finds that someone has parked a car outside his gate.','当他夜里回到家时,总是发现有人把车停在他家大门外。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',4,NULL,'Because of this, he has not been able to get his own car into his garage even once.','为此,他甚至一次也没能把自己的车开进车库。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',5,NULL,'Jasper has put up ''No Parking'' signs outside his gate, but these have not had any effect.','贾斯珀曾把几块''禁止停车''的牌子挂在大门外边,但没有任何效果。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',6,NULL,'Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen.','现在他把一个丑陋的石雕头像放在了大门上边,这是我见过的最丑陋的头像之一。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',7,NULL,'I asked him what it was and he told me that it was Medusa, the Gorgon.','我问他那是什么,他告诉我那是蛇发女怪美杜莎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l28',8,NULL,'Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!','贾斯珀希望她能把汽车和车主们都变成石头。但到目前为止还没有一个变成石头呢!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
