INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l29','has just + 过去分词','',NULL,'/hæz dʒʌst/','Captain Fawcett has just refused a request.','弗西特机长刚刚拒绝了一个请求。','I have just finished lunch.','我刚吃完午饭。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l29','since then','',NULL,'/sɪns ðen/','Since then, he has flown to many places.','从那以后,他已飞往许多地方。','Since then, things have changed.','从那以后,情况变了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l29','on another occasion','',NULL,'/ɑːn əˈnʌðər əˈkeɪʒən/','On another occasion, he landed in a parking lot.','还有一次,他降落在停车场。','On another occasion, we met again.','还有一次,我们又见面了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l29','carry passengers','',NULL,'/ˈkæri ˈpæsɪndʒərz/','This plane can carry seven passengers.','这架飞机能载七名乘客。','The bus can carry forty people.','这辆公交能载四十人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp1','choice','{"stem":"\"I ___ him in 1994.\"(有明确过去时间 in 1994,用一般过去)","options":["saw","had seen","have seen","see"],"answer_index":0,"stem_cn":"我1994年见到他。","explanation_cn":"有明确的过去时间 in 1994,用一般过去时 saw。✓ I saw him in 1994."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp1','choice','{"stem":"\"He ___ at this hotel last month.\"(last month:一般过去)","options":["stays","stayed","had stayed","has stayed"],"answer_index":1,"stem_cn":"上个月他住在这家酒店。","explanation_cn":"last month(上个月)是明确过去时间,用一般过去时 stayed。✓ He stayed at this hotel last month."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp1','choice','{"stem":"\"Captain Fawcett ___ not take him to Rockall.\"(过去某次、已结束:一般过去)","options":["did","have","has","was"],"answer_index":0,"stem_cn":"弗西特机长没送他去罗卡尔岛。","explanation_cn":"过去某次、已结束的事,用一般过去时;否定用 did not + 动词原形。✓ Captain Fawcett did not take him to Rockall."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp2','choice','{"stem":"\"I have not seen him ___ 1994.\"(接过去时间点:自从)","options":["ago","for","since","in"],"answer_index":2,"stem_cn":"自从1994年以来我没见过他。","explanation_cn":"since 接过去的时间点,表\"自从…以来\",配现在完成时。✓ I have not seen him since 1994."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp2','choice','{"stem":"\"Since then, he ___ flown passengers to many places.\"(与现在有联系:现在完成)","options":["did","has","was","had"],"answer_index":1,"stem_cn":"从那以后,他已把乘客送到许多地方。","explanation_cn":"since then 与现在有联系,用现在完成时;主语单数用 has + 过去分词。✓ Since then, he has flown passengers to many places."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp3','choice','{"stem":"\"I have not seen him ___ three years.\"(接一段时间:达三年)","options":["ago","since","for","in"],"answer_index":2,"stem_cn":"我三年没见过他了。","explanation_cn":"for 接一段时间,表\"持续多久\",配现在完成时。✓ I have not seen him for three years."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp3','choice','{"stem":"\"They ___ known each other for years.\"(持续多年:现在完成)","options":["are","have","did","had"],"answer_index":1,"stem_cn":"他们相识多年了。","explanation_cn":"\"相识多年(到现在)\"用现在完成时;主语 They 用 have + 过去分词。✓ They have known each other for years."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp4','choice','{"stem":"\"Have you ___ stayed at this hotel?\"(问经历''曾经'':现在完成)","options":["ever","since","ago","yet"],"answer_index":0,"stem_cn":"你在这家酒店住过吗?","explanation_cn":"ever 表\"曾经\",问经历,配现在完成时。✓ Have you ever stayed at this hotel?"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp4','choice','{"stem":"\"Up till now, I have ___ been abroad.\"(至今''从未'':现在完成)","options":["yet","ago","ever","never"],"answer_index":3,"stem_cn":"至今我还没出过国。","explanation_cn":"never 表\"从未\",问经历,配现在完成时,放在 have 和过去分词之间。✓ Up till now, I have never been abroad."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp4','choice','{"stem":"\"I have not been abroad ___.\"(现在完成句尾''以前'')","options":["ago","before","last year","then"],"answer_index":1,"stem_cn":"我以前没出过国。","explanation_cn":"before(以前)表经历,配现在完成时。✓ I have not been abroad before. ago / last year 是明确过去时间,要配一般过去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp5','choice','{"stem":"\"Captain Fawcett ___ bought an unusual taxi.\"(现在完成,主语单数)","options":["have","was","did","has"],"answer_index":3,"stem_cn":"弗西特机长买了一辆不寻常的出租车。","explanation_cn":"现在完成时\"刚买了\",主语单数用 has + 过去分词。✓ Captain Fawcett has bought an unusual taxi."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp5','choice','{"stem":"\"He has ___ a new service.\"(begin 的过去分词:开始了)","options":["beginning","began","begun","begin"],"answer_index":2,"stem_cn":"他开始了一项新业务。","explanation_cn":"现在完成时用过去分词;begin 的过去分词是 begun。✓ He has begun a new service."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp6','choice','{"stem":"\"She ___ to Paris last summer.\"(last summer,用一般过去时)","options":["went","has gone","goes","had gone"],"answer_index":0,"stem_cn":"她去年夏天去了巴黎。","explanation_cn":"last summer 是明确过去时间,用一般过去时;go 的过去式是 went。✓ She went to Paris last summer."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp6','choice','{"stem":"\"___ you ever eaten sushi?\"(ever,用现在完成时)","options":["Do","Were","Did","Have"],"answer_index":3,"stem_cn":"你吃过寿司吗?","explanation_cn":"ever(曾经)问经历,用现在完成时;疑问句用 Have + 主语 + 过去分词。✓ Have you ever eaten sushi?"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp7','choice','{"stem":"\"His first passenger was a doctor ___ flew to a village.\"(指人,作主语)","options":["which","whose","who","where"],"answer_index":2,"stem_cn":"他的第一位乘客是位飞往村庄的医生。","explanation_cn":"who 引导定语从句,指人,这里在从句里作主语。✓ a doctor who flew to a village."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp7','choice','{"stem":"\"The ''taxi'' ___ can land anywhere is a Swiss plane.\"(指物,作主语)","options":["whose","whom","who","which"],"answer_index":3,"stem_cn":"那辆能在任何地方降落的''出租车''是架瑞士飞机。","explanation_cn":"which 引导定语从句,指物,这里在从句里作主语。✓ The ''taxi'' which can land anywhere is a Swiss plane."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp8','choice','{"stem":"\"The most surprising thing is ___ it can land anywhere.\"(is 后引出后面的从句)","options":["which","who","that","what"],"answer_index":2,"stem_cn":"最令人惊奇的是它能在任何地方降落。","explanation_cn":"is 后面用 that 引导从句(说明主语\"是什么\")。✓ The most surprising thing is that it can land anywhere."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',5,'am2_l29_gp8','choice','{"stem":"\"The truth is ___ the trip was too dangerous.\"(is 后引出后面的从句)","options":["what","which","because","that"],"answer_index":3,"stem_cn":"事实是那次飞行太危险了。","explanation_cn":"is 后面用 that 引导从句。✓ The truth is that the trip was too dangerous."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"美语里\"飞机\"常说:","options":["fly car","airplane","aeroplane","air machine"],"answer_index":1,"explanation_cn":"美语\"飞机\"说 airplane;英式说 aeroplane。✓ a small airplane 一架小飞机。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"美语里\"停车场\"常说:","options":["car park","stop place","car field","parking lot"],"answer_index":3,"explanation_cn":"美语\"停车场\"说 parking lot;英式说 car park。✓ a deserted parking lot 一个废弃的停车场。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"lonely 的意思是:","options":["危险的","偏僻的;孤独的","热闹的","宽阔的"],"answer_index":1,"explanation_cn":"lonely = 偏僻的、孤独的。✓ a lonely village 偏僻的村庄。\n顺带记:热闹的 = busy;宽阔的 = wide;危险的 = dangerous."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"land(动词)的意思是:","options":["起飞","加速","坠毁","着陆,降落"],"answer_index":3,"explanation_cn":"land(动词)= 着陆、降落。✓ it can land anywhere 它能在任何地方降落。\n顺带记:起飞 = take off;坠毁 = crash;加速 = speed up."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"desert(动词)的意思是:","options":["打扫","遗弃,舍弃","装满","建造"],"answer_index":1,"explanation_cn":"desert(动词)= 遗弃、舍弃;deserted = 被遗弃的、荒废的。✓ a deserted parking lot 废弃的停车场。\n顺带记:建造 = build;打扫 = clean;装满 = fill."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',6,NULL,'choice','{"stem":"roof 的意思是:","options":["屋顶,楼顶","地下室","花园","走廊"],"answer_index":0,"explanation_cn":"roof = 屋顶、楼顶。✓ the roof of a building 一栋楼的屋顶。\n顺带记:地下室 = basement;走廊 = hallway;花园 = garden."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',7,NULL,'cloze','{"stem":"第 1 空","context":"Captain Fawcett ___1___ bought an unusual taxi. His first passenger ___2___ a doctor last year. Since then, he ___3___ flown to many places. But yesterday he ___4___ not take a man to Rockall.","blank_no":1,"options":["has","have","did","was"],"answer_index":0,"explanation_cn":"\"买了出租车\"与现在有联系(现在拥有),用现在完成时;主语单数用 has。✓ Captain Fawcett has bought an unusual taxi.\n✗ have:主语单数用 has;✗ did:did 是一般过去,不体现\"到现在\";✗ was:be 动词不构成现在完成."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',7,NULL,'cloze','{"stem":"第 2 空","context":"Captain Fawcett ___1___ bought an unusual taxi. His first passenger ___2___ a doctor last year. Since then, he ___3___ flown to many places. But yesterday he ___4___ not take a man to Rockall.","blank_no":2,"options":["was","has been","is","had been"],"answer_index":0,"explanation_cn":"有明确过去时间 last year,用一般过去时;主语单数用 was。✓ His first passenger was a doctor last year.\n✗ has been:last year 是明确过去时间,不用现在完成;✗ is:一般现在,时态不对;✗ had been:过去完成,这里没有\"过去的过去\"."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',7,NULL,'cloze','{"stem":"第 3 空","context":"Captain Fawcett ___1___ bought an unusual taxi. His first passenger ___2___ a doctor last year. Since then, he ___3___ flown to many places. But yesterday he ___4___ not take a man to Rockall.","blank_no":3,"options":["has","did","was","had"],"answer_index":0,"explanation_cn":"since then 与现在有联系,用现在完成时;主语单数用 has + 过去分词。✓ Since then, he has flown to many places.\n✗ did:since 配现在完成,不配一般过去;✗ was:be 不构成 has flown;✗ had:这里不是过去完成."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',7,NULL,'cloze','{"stem":"第 4 空","context":"Captain Fawcett ___1___ bought an unusual taxi. His first passenger ___2___ a doctor last year. Since then, he ___3___ flown to many places. But yesterday he ___4___ not take a man to Rockall.","blank_no":4,"options":["did","has","have","was"],"answer_index":0,"explanation_cn":"有明确过去时间 yesterday,用一般过去时;否定用 did not + 动词原形。✓ Yesterday he did not take a man to Rockall.\n✗ has:yesterday 是明确过去时间,不用现在完成;✗ have:同样不用现在完成且单复数不对;✗ was:be 不能这样用."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',8,NULL,'choice','{"stem":"What has Captain Fawcett bought?","options":["An unusual taxi — a small Swiss airplane","A large boat","A helicopter","A new sports car"],"answer_index":0,"explanation_cn":"课文说 Captain Fawcett has bought an unusual taxi… a small Swiss airplane,他买的是一架小型瑞士飞机当出租车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',8,NULL,'choice','{"stem":"What is the most surprising thing about the plane?","options":["It flies very fast","It can land almost anywhere","It is very cheap","It carries fifty people"],"answer_index":1,"explanation_cn":"课文说 the most surprising thing… is that it can land anywhere,最惊奇的是它几乎能在任何地方降落。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',8,NULL,'choice','{"stem":"Why did Captain Fawcett refuse the businessman?","options":["It was too far to fly","The man had no money","The plane was broken","The trip to Rockall was too dangerous"],"answer_index":3,"explanation_cn":"课文说 he did not take him because the trip was too dangerous,因为去罗卡尔岛太危险。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',9,NULL,'choice','{"stem":"你想说\"我1994年见过他\"(有明确过去时间用一般过去时):","options":["I saw him in 1994.","I see him in 1994.","I have seen him in 1994.","I had seen him in 1994."],"answer_index":0,"explanation_cn":"有明确的过去时间 in 1994,用一般过去时。✓ I saw him in 1994. 场合:说过去某个确定时间发生的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',9,NULL,'choice','{"stem":"你想说\"自从那以后我没见过他\"(since 与现在有联系,用现在完成时):","options":["I hadn''t seen him since then.","I haven''t seen him since then.","I didn''t see him since then.","I don''t see him since then."],"answer_index":1,"explanation_cn":"since(自从)与现在有联系,用现在完成时。✓ I haven''t seen him since then. 场合:说从过去某时到现在一直没做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',9,NULL,'choice','{"stem":"你想说\"你去过国外吗?\"(问经历用 Have you ever been):","options":["Are you ever abroad?","Have you ever went abroad?","Have you ever been abroad?","Did you ever been abroad?"],"answer_index":2,"explanation_cn":"问\"有没有做过(经历)\"用 Have you ever + 过去分词。✓ Have you ever been abroad? 场合:问对方有没有某段经历。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"plow 的意思是:","options":["浇水","播种","收割","耕(地)"],"answer_index":3,"explanation_cn":"plow = 耕(地)(美语拼写;英式 plough)。✓ a plowed field 耕过的田。\n顺带记:收割 = harvest;浇水 = water;播种 = sow."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"block 的意思是:","options":["一个洞","一条河","一大楼;街区","一扇门"],"answer_index":2,"explanation_cn":"block = 一大楼、一个街区。✓ a block of flats 一栋公寓楼。\n顺带记:一扇门 = a door;一条河 = a river;一个洞 = a hole."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"\"She ___ to Paris last summer.\"(last summer,用一般过去时)","options":["has gone","went","had gone","goes"],"answer_index":1,"stem_cn":"她去年夏天去了巴黎。","explanation_cn":"last summer 是明确过去时间,用一般过去时;go 的过去式是 went。✓ She went to Paris last summer."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"\"___ you ever flown in a small plane?\"(ever,用现在完成时)","options":["Did","Were","Have","Do"],"answer_index":2,"stem_cn":"你坐过小飞机吗?","explanation_cn":"ever(曾经)问经历,用现在完成时;疑问用 Have + 主语 + 过去分词。✓ Have you ever flown in a small plane?"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"\"It can land anywhere.\" 这句话的意思是:","options":["它只能在机场降落。","它降落得很慢。","它不能降落。","它能在任何地方降落。"],"answer_index":3,"explanation_cn":"It can land anywhere. 意思是\"它能在任何地方降落\"。land = 着陆。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"\"The trip was too dangerous.\" 这句话的意思是:","options":["那次飞行很便宜。","那次飞行很有趣。","那次飞行太危险了。","那次飞行很短。"],"answer_index":2,"explanation_cn":"The trip was too dangerous. 意思是\"那次飞行太危险了\"。too = 太、过于。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"Who was Captain Fawcett''s first passenger?","options":["A pilot from Birmingham","A doctor flying to a village in the Welsh mountains","A farmer with a plowed field","A businessman going to Rockall"],"answer_index":1,"passage":"Captain Ben Fawcett has bought an unusual taxi and has begun a new service. The ''taxi'' is a small Swiss airplane called a ''Pilatus Porter''. This wonderful plane can carry seven passengers. The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a plowed field. Captain Fawcett''s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains. Since then, Captain Fawcett has flown passengers to many unusual places. Once he landed on the roof of an apartment building and on another occasion, he landed in a deserted parking lot. Captain Fawcett has just refused a strange request from a businessman. The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.","explanation_cn":"课文说 first passenger was a doctor who flew… to a lonely village in the Welsh mountains,第一位乘客是飞往威尔士山村的医生。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"Where has Captain Fawcett landed his plane?","options":["Only on water","Only at big airports","On snow, water, a roof, and a deserted parking lot","Only in the mountains"],"answer_index":2,"passage":"Captain Ben Fawcett has bought an unusual taxi and has begun a new service. The ''taxi'' is a small Swiss airplane called a ''Pilatus Porter''. This wonderful plane can carry seven passengers. The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a plowed field. Captain Fawcett''s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains. Since then, Captain Fawcett has flown passengers to many unusual places. Once he landed on the roof of an apartment building and on another occasion, he landed in a deserted parking lot. Captain Fawcett has just refused a strange request from a businessman. The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.","explanation_cn":"课文说它能在雪地、水面降落,还降落过屋顶和废弃停车场。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"Does Captain Fawcett think any trip is too dangerous?","options":["Yes — he refused to fly to Rockall","Only night trips","Only trips over water","No, he flies anywhere"],"answer_index":0,"audio":"Captain Ben Fawcett has bought an unusual taxi and has begun a new service. The ''taxi'' is a small Swiss airplane called a ''Pilatus Porter''. This wonderful plane can carry seven passengers. The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a plowed field. Captain Fawcett''s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains. Since then, Captain Fawcett has flown passengers to many unusual places. Once he landed on the roof of an apartment building and on another occasion, he landed in a deserted parking lot. Captain Fawcett has just refused a strange request from a businessman. The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.","explanation_cn":"课文说他拒绝了去罗卡尔岛,因为太危险,可见他认为有的飞行太危险。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l29',10,NULL,'choice','{"stem":"How many passengers can the plane carry?","options":["Two","Twenty","Seven","Fifty"],"answer_index":2,"audio":"Captain Ben Fawcett has bought an unusual taxi and has begun a new service. The ''taxi'' is a small Swiss airplane called a ''Pilatus Porter''. This wonderful plane can carry seven passengers. The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a plowed field. Captain Fawcett''s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains. Since then, Captain Fawcett has flown passengers to many unusual places. Once he landed on the roof of an apartment building and on another occasion, he landed in a deserted parking lot. Captain Fawcett has just refused a strange request from a businessman. The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.","explanation_cn":"课文说 This wonderful plane can carry seven passengers,能载七名乘客。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
